#!/usr/bin/env python3
"""Build C test fixtures via Docker and copy them into _autogenerated/."""

import shutil
import subprocess
import sys
import tempfile
import uuid
from pathlib import Path

PACKAGE_DIR = Path(__file__).parent.parent.resolve()
DOCKERFILE = PACKAGE_DIR / "Dockerfile"
AUTOGEN_DIR = PACKAGE_DIR / "_autogenerated"
IMAGE_NAME = "ida-test-builder"


def sh(cmd: list[str]) -> None:
    result = subprocess.run(cmd, text=True)
    if result.returncode != 0:
        print(result.stderr.strip(), file=sys.stderr)
        sys.exit(result.returncode)


def main() -> None:
    # 1. Invariants
    if not shutil.which("docker"):
        sys.exit("docker not found on PATH")
    if not DOCKERFILE.exists():
        sys.exit(f"Dockerfile not found: {DOCKERFILE}")

    # 2. Build
    sh(["docker", "build", "-t", IMAGE_NAME, "-f", str(DOCKERFILE), str(PACKAGE_DIR)])

    # 3. Copy
    container = f"ida-test-extract-{uuid.uuid4().hex[:8]}"
    subprocess.run(["docker", "create", "--name", container, IMAGE_NAME], capture_output=True)
    try:
        with tempfile.TemporaryDirectory() as tmp:
            sh(["docker", "cp", f"{container}:/out/.", tmp])
            if AUTOGEN_DIR.exists():
                shutil.rmtree(AUTOGEN_DIR)
            shutil.copytree(tmp, AUTOGEN_DIR)
    finally:
        subprocess.run(["docker", "rm", container], capture_output=True)

    # 4. Permissions
    for binary in (AUTOGEN_DIR / "linux").iterdir():
        binary.chmod(binary.stat().st_mode | 0o755)


if __name__ == "__main__":
    main()
